SourceCode.Declaration:
/// <summary>
/// Handheld sign-in and self-service password change.
///
/// **Two layers of identity, and they answer different questions.** The device authenticates to
/// D365FO with a service principal, which proves the *app* may talk to the system. That says
/// nothing about who is holding the device - and every device shares it, so on its own every
/// posting would carry the same CreatedBy and a GRN could never tell you who received the pallet.
/// This service adds the second layer: which worker.
///
/// Consequences that shape everything below:
///
/// - **A wrong user name and a wrong password give the same answer.** Distinguishing them tells
///   an attacker which accounts exist, which is half the problem solved for them.
/// - **There is no administration here.** Creating users, resetting other people's passwords
///   and deactivating accounts happen in D365FO, where D365FO's own security decides who may do
///   them. The handheld signs people in; it does not manage them.
/// - **Failed attempts lock the account for a while**, not for ever. A permanent lock needs an
///   administrator, and on a night shift with nobody to call that stops the work.
///
/// Passwords arrive here, are verified or hashed, and are never stored, echoed or logged.
/// </summary>
class HSMobileOpsUserService
{
    private const int MaxFailedAttempts = 5;
    private const int LockoutMinutes    = 15;
    // How long before expiry an otherwise-successful sign-in starts carrying a renewal warning -
    // see the license-check block in signIn and HSMobileOpsSignInResponse::parmLicenseWarning.
    private const int LicenseWarningDays = 30;

}

Method.Source:
/// <summary>
/// Signs a worker in and returns their identity and the warehouses they may work in.
///
/// `final`, `[Wrappable(false)]` and `[Hookable(false)]` - not overridable and not a Chain of
/// Command or event-handler extension point, by any of the three mechanisms - so nothing can
/// wrap this method to skip or override the license/device-limit gate at its top. See the
/// class doc on HSMobileOpsLicense for why that gate would otherwise be pointless no matter
/// how strong its own cryptography is. This gate is a defense-in-depth safety net beneath the
/// Android app's own pre-flight certificate/license/device checks (HSMobileOpsLicenseSvc) -
/// kept here, not removed, since a modified client could in principle skip its own checks and
/// call signIn directly.
/// </summary>
[Wrappable(false), Hookable(false)]
public final HSMobileOpsSignInResponse signIn(HSMobileOpsSignInRequest _request)
{
    HSMobileOpsSignInResponse response = new HSMobileOpsSignInResponse();
    HSMobileOpsLicenseStatus  license;
    HSMobileOpsUser           user;
    DataAreaId                company;
    str                       userName;
    str                       password;
    str                       deviceId;
    boolean                   ok;

    response.parmSuccess(false);
    response.parmWarehouses(new List(Types::Class));
    response.parmModulePermissions(new List(Types::Class));

    if (_request)
    {
        company  = _request.parmDataAreaId();
        userName = _request.parmUserName();
        password = _request.parmPassword();
        deviceId = _request.parmDeviceId();
    }

    if (!company || !userName || !password || !CompanyInfo::findDataArea(company).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('Company, user name and password are all required');
        return response;
    }

    // License and device-fleet state are both environment-wide (HSMobileOpsLicenseSetup is
    // SaveDataPerCompany=No; HSMobileOpsDevice's own methods query crossCompany) - checked here,
    // ahead of changecompany and ahead of touching HSMobileOpsUser at all, so a license problem
    // is never confused with a wrong password and blocks every company alike. See
    // HSMobileOpsLicense for the certificate/license chain and HSMobileOpsDevice::checkDeviceLimit
    // for why this only ever turns away a device D365FO has never seen before - a device already
    // in the fleet always passes, exactly the same "never kicks someone already in" spirit as the
    // account-lockout and inactive-account checks below.
    license = HSMobileOpsLicense::verify();
    if (!license.parmValid())
    {
        response.parmErrorCode(license.parmErrorCode());
        response.parmMessage(license.parmMessage());
        return response;
    }

    if (deviceId && !HSMobileOpsDevice::checkDeviceLimit(deviceId, license.parmMaxDevices()))
    {
        response.parmErrorCode('DEVICE_LIMIT_REACHED');
        response.parmMessage(strFmt(
            'This app is licensed for %1 device(s), and that many are already active. Contact your administrator.',
            license.parmMaxDevices()));
        return response;
    }

    // Renewal notice, not a block - the license is valid, this sign-in proceeds either way.
    // Set now so it survives every path below (credential failures return before reaching
    // here are unaffected; a successful sign-in carries it through untouched).
    if (license.parmDaysUntilExpiry() <= LicenseWarningDays)
    {
        response.parmLicenseWarning(strFmt(
            "This app's license expires in %1 day(s) (on %2). Contact your administrator to renew.",
            license.parmDaysUntilExpiry(), license.parmExpiryUtc()));
    }

    changecompany (company)
    {
        user = null;
        user = HSMobileOpsUser::find(userName, true);

        // Deliberately identical to the wrong-password answer below. Anything that
        // distinguishes "no such user" from "wrong password" enumerates accounts.
        if (!user.RecId)
        {
            response.parmErrorCode('INVALID_CREDENTIALS');
            response.parmMessage('That user name and password do not match');
            return response;
        }

        if (user.isLockedOut())
        {
            response.parmErrorCode('LOCKED_OUT');
            response.parmMessage(strFmt(
                'Too many failed attempts. Try again after %1.',
                DateTimeUtil::toStr(user.LockedUntilUtc)));
            return response;
        }

        if (user.IsActive != NoYes::Yes)
        {
            response.parmErrorCode('INACTIVE');
            response.parmMessage('This account has been deactivated');
            return response;
        }

        ok = HSMobileOpsPassword::verify(
            password, user.PasswordHash, user.PasswordSalt, user.HashIterations);

        ttsbegin;
        if (!ok)
        {
            HSMobileOpsUserService::recordFailure(user);
            ttscommit;

            response.parmErrorCode('INVALID_CREDENTIALS');
            response.parmMessage('That user name and password do not match');
            return response;
        }

        user.FailedAttempts = 0;
        user.LockedUntilUtc = DateTimeUtil::minValue();
        user.LastSignInUtc  = DateTimeUtil::utcNow();
        user.update();
        ttscommit;

        response.parmUserName(user.UserName);
        response.parmDisplayName(user.DisplayName);
        response.parmPersonnelNumber(user.PersonnelNumber);
        response.parmIsSupervisor(user.IsSupervisor == NoYes::Yes);
        response.parmIsCycleCountSupervisor(user.IsCycleCountSupervisor == NoYes::Yes);
        response.parmMaxOverPercent(user.MaxOverPercent);
        response.parmMaxOverQty(user.MaxOverQty);
        response.parmMustChangePassword(user.MustChangePassword == NoYes::Yes);

        HSMobileOpsUserService::appendWarehouses(response, user.RecId);
        HSMobileOpsUserService::appendModulePermissions(response, user.RecId);

        if (!response.parmWarehouses().elements())
        {
            // Signed in but with nowhere to work. Reported as its own outcome: the fix is an
            // administrator assigning a warehouse, not the worker retyping their password.
            response.parmErrorCode('NO_WAREHOUSE');
            response.parmMessage('No warehouse is assigned to this user');
            return response;
        }

        // Fleet registration piggybacks on a real sign-in rather than being its own call -
        // the device id, brand and model are already on this same request, and a successful
        // sign-in is exactly the moment a device's identity is trustworthy. Never blocks the
        // sign-in itself: a fleet-list row is a nice-to-have for IT, not something a worker
        // should be locked out of the app over.
        HSMobileOpsUserService::registerDevice(_request, response, user.UserName);

        response.parmSuccess(true);
    }

    return response;
}

/// <summary>
/// The warehouses assigned to a user, with exactly one marked default.
///
/// If the data has no default flagged and there is exactly one assignment, that one is
/// returned as the default - an administrative slip should not cost a worker their shift.
/// Where several are assigned and none flagged, none is defaulted and the app asks.
/// </summary>
private static void appendWarehouses(HSMobileOpsSignInResponse _response, RefRecId _userRecId)
{
    HSMobileOpsUserWarehouse       assignment;
    InventLocation                 inventLocation;
    HSMobileOpsWarehouseAssignment contract;
    HSMobileOpsUserWarehouse       defaultAssignment;
    List                           warehouses = _response.parmWarehouses();

    defaultAssignment = HSMobileOpsUserWarehouse::findDefault(_userRecId);

    while select SiteId, WarehouseId, IsDefault, RecId from assignment
        order by assignment.WarehouseId
        where assignment.UserRecId == _userRecId
        outer join Name from inventLocation
            where inventLocation.InventLocationId == assignment.WarehouseId
    {
        contract = new HSMobileOpsWarehouseAssignment();

        contract.parmSiteId(assignment.SiteId);
        contract.parmWarehouseId(assignment.WarehouseId);
        contract.parmWarehouseName(inventLocation.Name);
        contract.parmIsDefault(assignment.RecId == defaultAssignment.RecId);

        warehouses.addEnd(contract);
    }
}

/// <summary>
/// Every module this worker has been explicitly touched for - see
/// HSMobileOpsSignInResponse::parmModulePermissions for what an empty list means.
/// </summary>
private static void appendModulePermissions(HSMobileOpsSignInResponse _response, RefRecId _userRecId)
{
    HSMobileOpsUserModulePermission permission;
    HSMobileOpsModulePermission     contract;
    List                            modulePermissions = _response.parmModulePermissions();

    while select Module, IsAllowed from permission
        where permission.UserRecId == _userRecId
    {
        contract = new HSMobileOpsModulePermission();
        contract.parmModule(HSMobileOpsUserService::moduleToCode(permission.Module));
        contract.parmIsAllowed(permission.IsAllowed == NoYes::Yes);
        modulePermissions.addEnd(contract);
    }
}

/// <summary>
/// HSMobileOpsModule -> the wire string the app's WarehouseWorkflow enum matches by exact
/// name. Kept as an explicit switch, not enum2str - the wire contract must survive the
/// X++ enum being reordered or relabeled, and a switch is what makes that a one-line review
/// instead of a silent break.
/// </summary>
private static str moduleToCode(HSMobileOpsModule _module)
{
    switch (_module)
    {
        case HSMobileOpsModule::PO_RECEIVING:    return 'PO_RECEIVING';
        case HSMobileOpsModule::TRANSFER_SHIP:   return 'TRANSFER_SHIP';
        case HSMobileOpsModule::TRANSFER_RECEIVE: return 'TRANSFER_RECEIVE';
        case HSMobileOpsModule::INVENTORY_COUNT: return 'INVENTORY_COUNT';
        default: return '';
    }
}

/// <summary>
/// The inverse of moduleToCode. Returns -1 for anything unrecognised (an older app talking
/// to a newer AOS, or a typo) - callers check for that rather than silently defaulting to
/// element 0, which would quietly target the wrong module.
/// </summary>
private static HSMobileOpsModule moduleFromCode(str _code)
{
    switch (_code)
    {
        case 'PO_RECEIVING':     return HSMobileOpsModule::PO_RECEIVING;
        case 'TRANSFER_SHIP':    return HSMobileOpsModule::TRANSFER_SHIP;
        case 'TRANSFER_RECEIVE': return HSMobileOpsModule::TRANSFER_RECEIVE;
        case 'INVENTORY_COUNT':  return HSMobileOpsModule::INVENTORY_COUNT;
        default: return -1;
    }
}

/// <summary>
/// Upserts this handheld's fleet row - see HSMobileOpsDevice::registerSignIn.
///
/// Reads the default warehouse back out of the response this same request just built in
/// appendWarehouses, rather than re-querying HSMobileOpsUserWarehouse - the answer is already
/// in hand. Wrapped in its own try/catch so that a problem in the fleet table - a full disk,
/// a lock timeout, anything - never turns into a worker unable to start their shift over a
/// feature that exists purely for IT's benefit.
///
/// Catches plain `catch` (every Exception value), not `catch (Exception::Error)` - confirmed
/// live as a real gap, not a theoretical one: a DuplicateKeyException from registerSignIn
/// propagated straight through the narrower clause and turned into an HTTP 500 that blocked
/// sign-in entirely, exactly the outcome this try/catch exists to prevent. X++'s Exception
/// enum has many distinct values (Error, DuplicateKeyException, Deadlock, CLRError, ...) and
/// a clause naming one only ever catches that one - "anything" in the paragraph above needs
/// the catch-all to actually mean anything.
/// </summary>
private static void registerDevice(
    HSMobileOpsSignInRequest  _request,
    HSMobileOpsSignInResponse _response,
    HSMobileOpsUserName       _userName)
{
    ListEnumerator                 enumerator;
    HSMobileOpsWarehouseAssignment assignment;
    InventSiteId                   siteId;
    InventLocationId               warehouseId;

    enumerator = _response.parmWarehouses().getEnumerator();
    while (enumerator.moveNext())
    {
        assignment = enumerator.current();
        if (assignment.parmIsDefault())
        {
            siteId      = assignment.parmSiteId();
            warehouseId = assignment.parmWarehouseId();
            break;
        }
    }

    try
    {
        HSMobileOpsDevice::registerSignIn(
            _request.parmDeviceId(),
            _request.parmDeviceBrand(),
            _request.parmDeviceModel(),
            _request.parmPlatform(),
            _request.parmPlatformVersion(),
            _request.parmAppVersionName(),
            _userName,
            siteId,
            warehouseId);
    }
    catch
    {
        // Deliberately not HSMobileOpsPostingService::lastError() - that method is private
        // to its own class, and this failure is a diagnostic nicety, not something worth a
        // cross-class dependency for. The device id alone is enough to go looking.
        warning(strFmt(
            'HSMobileOpsDevice registration failed for device %1', _request.parmDeviceId()));
    }
}

/// <summary>
/// Counts a failed attempt and locks the account once there have been too many.
///
/// Time-boxed. The overwhelming majority of failures are a mistyped password on a small
/// keyboard, and the response to that should be a wait, not a phone call.
/// </summary>
private static void recordFailure(HSMobileOpsUser _user)
{
    _user.FailedAttempts += 1;

    if (_user.FailedAttempts >= MaxFailedAttempts)
    {
        _user.LockedUntilUtc = DateTimeUtil::addMinutes(
            DateTimeUtil::utcNow(), LockoutMinutes);
        _user.FailedAttempts = 0;
    }

    _user.update();
}

/// <summary>
/// A worker changing their own password.
///
/// The current password is required even when a change is being forced. Without it, anyone
/// who picks up an unlocked handheld mid-shift can lock the worker out of their own account.
/// </summary>
public HSMobileOpsChangePasswordResponse changePassword(HSMobileOpsChangePasswordRequest _request)
{
    HSMobileOpsChangePasswordResponse response = new HSMobileOpsChangePasswordResponse();
    HSMobileOpsUser          user;
    DataAreaId               company;
    str                      userName;
    str                      currentPassword;
    str                      newPassword;
    str                      policyProblem;
    str                      salt;

    response.parmSuccess(false);

    if (_request)
    {
        company         = _request.parmDataAreaId();
        userName        = _request.parmUserName();
        currentPassword = _request.parmCurrentPassword();
        newPassword     = _request.parmNewPassword();
    }

    if (!company || !userName || !currentPassword || !newPassword
     || !CompanyInfo::findDataArea(company).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    policyProblem = HSMobileOpsPassword::policyFailure(newPassword);
    if (policyProblem)
    {
        response.parmErrorCode('POLICY');
        response.parmMessage(policyProblem);
        return response;
    }

    changecompany (company)
    {
        user = null;
        user = HSMobileOpsUser::find(userName, true);

        if (!user.RecId
         || user.IsActive != NoYes::Yes
         || !HSMobileOpsPassword::verify(
                currentPassword, user.PasswordHash, user.PasswordSalt, user.HashIterations))
        {
            response.parmErrorCode('INVALID_CREDENTIALS');
            response.parmMessage('That user name and password do not match');
            return response;
        }

        salt = HSMobileOpsPassword::newSalt();

        ttsbegin;
        user.PasswordSalt       = salt;
        user.HashIterations     = HSMobileOpsPassword::defaultIterations();
        user.PasswordHash       = HSMobileOpsPassword::hash(newPassword, salt, user.HashIterations);
        user.MustChangePassword = NoYes::No;
        user.FailedAttempts     = 0;
        user.LockedUntilUtc     = DateTimeUtil::minValue();
        user.update();
        ttscommit;

        response.parmSuccess(true);
    }

    return response;
}

/// <summary>
/// An admin toggling one worker's access to one of the four handheld modules.
///
/// **The client's own claim of being a supervisor is never trusted for the write itself** -
/// only for the local UI gating that got the operator to this screen in the first place. This
/// method re-looks-up ActingUserName and checks HSMobileOpsUser.IsSupervisor fresh, the same
/// way HSMobileOpsUserAdmin's form-side methods rely on D365FO's own security instead of a
/// client-supplied flag. A rooted device that patches its own cached role can change what its
/// own UI shows; it cannot grant itself, or anyone else, a permission that survives this
/// check.
///
/// No password re-check, deliberately consistent with the rest of this app: postings already
/// identify their acting worker by UserName alone (see HSMobileOpsPostRequest), trusting the
/// device to report whichever worker is currently signed in - there is no per-call session
/// token anywhere in this service today for this to plug into. IsSupervisor is exactly the
/// same trust boundary applied one level up.
/// </summary>
public HSMobileOpsSetModulePermissionResponse setModulePermission(
    HSMobileOpsSetModulePermissionRequest _request)
{
    HSMobileOpsSetModulePermissionResponse response = new HSMobileOpsSetModulePermissionResponse();
    HSMobileOpsUser                        actingUser;
    HSMobileOpsUser                        targetUser;
    HSMobileOpsModule                      module;
    HSMobileOpsUserModulePermission        permission;
    DataAreaId                             company;

    response.parmSuccess(false);

    if (!_request
     || !_request.parmDataAreaId()
     || !_request.parmActingUserName()
     || !_request.parmTargetUserName()
     || !_request.parmModule())
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('Company, acting user, target user and module are all required');
        return response;
    }

    company = _request.parmDataAreaId();
    module  = HSMobileOpsUserService::moduleFromCode(_request.parmModule());

    if (module == -1)
    {
        response.parmErrorCode('INVALID_MODULE');
        response.parmMessage(strFmt('Unrecognised module %1', _request.parmModule()));
        return response;
    }

    changecompany (company)
    {
        actingUser = HSMobileOpsUser::find(_request.parmActingUserName());
        if (!actingUser.RecId)
        {
            response.parmErrorCode('ACTING_USER_NOT_FOUND');
            response.parmMessage('The signed-in user could not be re-verified');
            return response;
        }

        if (actingUser.IsSupervisor != NoYes::Yes)
        {
            response.parmErrorCode('NOT_SUPERVISOR');
            response.parmMessage('Only a supervisor may change module access');
            return response;
        }

        targetUser = HSMobileOpsUser::find(_request.parmTargetUserName());
        if (!targetUser.RecId)
        {
            response.parmErrorCode('TARGET_USER_NOT_FOUND');
            response.parmMessage(strFmt('No mobile user %1', _request.parmTargetUserName()));
            return response;
        }

        ttsbegin;
        select forUpdate permission
            where permission.UserRecId == targetUser.RecId
               && permission.Module    == module;

        if (!permission.RecId)
        {
            permission.UserRecId = targetUser.RecId;
            permission.Module    = module;
            permission.insert();
        }

        permission.IsAllowed = _request.parmIsAllowed() ? NoYes::Yes : NoYes::No;
        permission.update();
        ttscommit;

        response.parmSuccess(true);
    }

    return response;
}

/// <summary>
/// Every active mobile worker, for the Admin Center's own list. Re-validates
/// ActingUserName is a current supervisor server-side, same reasoning as
/// setModulePermission - the Admin Center menu entry being hidden client-side for a
/// non-supervisor is UX, not the security boundary.
/// </summary>
public HSMobileOpsWorkerDirectoryResponse getWorkerDirectory(
    HSMobileOpsWorkerDirectoryRequest _request)
{
    HSMobileOpsWorkerDirectoryResponse response = new HSMobileOpsWorkerDirectoryResponse();
    HSMobileOpsUser                    actingUser;
    HSMobileOpsUser                    worker;
    HSMobileOpsWorkerSummary           contract;
    List                               workers = new List(Types::Class);
    DataAreaId                         company;

    response.parmSuccess(false);
    response.parmWorkers(workers);

    if (!_request || !_request.parmDataAreaId() || !_request.parmActingUserName())
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    company = _request.parmDataAreaId();

    changecompany (company)
    {
        actingUser = HSMobileOpsUser::find(_request.parmActingUserName());
        if (!actingUser.RecId)
        {
            response.parmErrorCode('ACTING_USER_NOT_FOUND');
            return response;
        }

        if (actingUser.IsSupervisor != NoYes::Yes)
        {
            response.parmErrorCode('NOT_SUPERVISOR');
            response.parmMessage('Only a supervisor may browse other workers');
            return response;
        }

        while select UserName, DisplayName, IsSupervisor from worker
            order by worker.DisplayName
            where worker.IsActive == NoYes::Yes
        {
            contract = new HSMobileOpsWorkerSummary();
            contract.parmUserName(worker.UserName);
            contract.parmDisplayName(worker.DisplayName);
            contract.parmIsSupervisor(worker.IsSupervisor == NoYes::Yes);
            workers.addEnd(contract);
        }

        response.parmSuccess(true);
    }

    return response;
}
